{
  "name": "@nimble-way/opencode",
  "version": "0.1.1",
  "description": "Nimble web search and data tools for OpenCode",
  "type": "module",
  "license": "MIT",
  "author": "Nimble <https://nimbleway.com>",
  "homepage": "https://github.com/Nimbleway/opencode-nimble",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Nimbleway/opencode-nimble.git"
  },
  "bugs": {
    "url": "https://github.com/Nimbleway/opencode-nimble/issues"
  },
  "keywords": [
    "nimble",
    "opencode",
    "opencode-plugin",
    "web-search",
    "search",
    "extract",
    "tool"
  ],
  "files": [
    "dist",
    "src"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "prepare": "tsc",
    "typecheck": "tsc -p tsconfig.tests.json",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5 <3",
    "effect": "^4.0.6"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "effect": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.5",
    "@types/node": "^24.0.0",
    "effect": "4.1.0",
    "typescript": "^5.9.0",
    "vitest": "^5.1.0"
  },
  "engines": {
    "opencode": ">=2.2.5",
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "packageManager": "pnpm@11.1.3"
}
